#include <stdlib.h>
typedef struct{int**a,n,cap;}SummaryRanges;SummaryRanges* summaryRangesCreate(){SummaryRanges*x=malloc(sizeof(*x));x->n=0;x->cap=16;x->a=malloc(x->cap*sizeof(int*));return x;}void summaryRangesAddNum(SummaryRanges*x,int v){int i=0;while(i<x->n&&x->a[i][1]<v-1)i++;if(i<x->n&&x->a[i][0]<=v+1){if(v<x->a[i][0])x->a[i][0]=v;if(v>x->a[i][1])x->a[i][1]=v;while(i+1<x->n&&x->a[i+1][0]<=x->a[i][1]+1){if(x->a[i+1][1]>x->a[i][1])x->a[i][1]=x->a[i+1][1];free(x->a[i+1]);for(int j=i+1;j+1<x->n;j++)x->a[j]=x->a[j+1];x->n--;}}else{if(x->n==x->cap){x->cap*=2;x->a=realloc(x->a,x->cap*sizeof(int*));}for(int j=x->n;j>i;j--)x->a[j]=x->a[j-1];x->a[i]=malloc(2*sizeof(int));x->a[i][0]=x->a[i][1]=v;x->n++;}}int** summaryRangesGetIntervals(SummaryRanges*x,int*rs,int**rc){int**o=malloc(x->n*sizeof(int*));*rc=malloc(x->n*sizeof(int));for(int i=0;i<x->n;i++){o[i]=malloc(2*sizeof(int));o[i][0]=x->a[i][0];o[i][1]=x->a[i][1];(*rc)[i]=2;}*rs=x->n;return o;}void summaryRangesFree(SummaryRanges*x){for(int i=0;i<x->n;i++)free(x->a[i]);free(x->a);free(x);}
